$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$row=['title'=>'','description'=>'','image'=>'','project_url'=>'','technologies'=>'[]','features'=>'[]','sort_order'=>0,'is_active'=>1];if($id){$s=$pdo->prepare('SELECT * FROM projects WHERE id=?');$s->execute([$id]);$row=$s->fetch()?:$row;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$list=function(string $key):string{$items=array_values(array_filter(array_map('trim',preg_split('/\r\n|\r|\n/',(string)($_POST[$key]??'')))));return json_encode($items);};$data=[trim((string)$_POST['title']),trim((string)$_POST['description']),trim((string)$_POST['image']),trim((string)$_POST['project_url']),$list('technologies'),$list('features'),max(0,(int)$_POST['sort_order']),isset($_POST['is_active'])?1:0];if($id){$s=$pdo->prepare('UPDATE projects SET title=?,description=?,image=?,project_url=?,technologies=?,features=?,sort_order=?,is_active=? WHERE id=?');$s->execute([...$data,$id]);flash('success','Project updated.');}else{$s=$pdo->prepare('INSERT INTO projects (title,description,image,project_url,technologies,features,sort_order,is_active) VALUES (?,?,?,?,?,?,?,?)');$s->execute($data);flash('success','Project created.');}admin_redirect('projects.php');}
